Connection& Pool::acquire(const std::string& tenant) {
    if (tenant.empty())
        throw std::invalid_argument("tenant required");   // fail at the entry
    if (slots_.size() == capacity_)
        throw PoolExhausted("no slot for " + tenant);     // refuse, do not queue
    auto conn = std::make_unique<Connection>(dial(tenant));
    slots_.push_back(std::move(conn));                      // frees on later throw
    return *slots_.back();
}

